// src/client/sparkleSystem.ts
var SPARKLE_SRC = "assets/scene/Particles/sparkle.png";
var BURST_COUNT = 10;
var BURST_POOL_SIZE = 14;
var SPARKLE_SIZE = 0.22;
var SPEED_MIN = 1.6;
var SPEED_MAX = 3.8;
var GRAVITY = 4.5;
var LIFE_BASE_MS = 1100;
var LIFE_VARY_MS = 350;
var SPAWN_Y = 0.4;
var POP_IN = 0.2;
var HOLD_END = 0.5;
var pool = [];
function makeSparkleEntity() {
  const e = engine.addEntity();
  MeshRenderer3.setPlane(e);
  Material3.setPbrMaterial(e, {
    texture: Material3.Texture.Common({ src: SPARKLE_SRC }),
    alphaTexture: Material3.Texture.Common({ src: SPARKLE_SRC }),
    albedoColor: Color42.create(1, 0.95, 0.75, 1),
    // warm cream-gold
    emissiveColor: { r: 1, g: 0.85, b: 0.4 },
    // gold glow
    emissiveIntensity: 1.8,
    transparencyMode: MaterialTransparencyMode.MTM_ALPHA_BLEND
  });
  Billboard2.create(e, { billboardMode: BillboardMode.BM_ALL });
  Transform2.create(e, {
    position: { x: 0, y: -100, z: 0 },
    scale: { x: 1e-3, y: 1e-3, z: 1e-3 }
  });
  return e;
}
function initSparkleSystem() {
  for (let i = 0; i < BURST_POOL_SIZE; i++) {
    pool.push({
      entity: makeSparkleEntity(),
      active: false,
      pos: { x: 0, y: 0, z: 0 },
      vel: { x: 0, y: 0, z: 0 },
      lifeMs: 0,
      maxLifeMs: 0
    });
  }
  engine.addSystem((dt) => {
    for (const s of pool) {
      if (!s.active)
        continue;
      s.lifeMs += dt * 1e3;
      s.vel.y -= GRAVITY * dt;
      s.pos.x += s.vel.x * dt;
      s.pos.y += s.vel.y * dt;
      s.pos.z += s.vel.z * dt;
      if (s.lifeMs >= s.maxLifeMs) {
        s.active = false;
        Transform2.getMutable(s.entity).scale = { x: 1e-3, y: 1e-3, z: 1e-3 };
        continue;
      }
      const t = Math.min(s.lifeMs / s.maxLifeMs, 1);
      let sc;
      if (t < POP_IN) {
        const u = t / POP_IN;
        sc = SPARKLE_SIZE * (1 - (1 - u) * (1 - u));
      } else if (t < HOLD_END) {
        sc = SPARKLE_SIZE;
      } else {
        sc = SPARKLE_SIZE * (1 - (t - HOLD_END) / (1 - HOLD_END));
      }
      const tf = Transform2.getMutable(s.entity);
      tf.position = { x: s.pos.x, y: s.pos.y, z: s.pos.z };
      tf.scale = { x: sc, y: sc, z: sc };
    }
  });
  console.log(`[Sparkles] Pool ready \u2014 ${BURST_POOL_SIZE} slots`);
}
function playSparkle(pos) {
  let claimed = 0;
  for (const s of pool) {
    if (claimed >= BURST_COUNT)
      break;
    if (s.active)
      continue;
    const azimuth = Math.random() * Math.PI * 2;
    const elevation = (25 + Math.random() * 65) * (Math.PI / 180);
    const speed = SPEED_MIN + Math.random() * (SPEED_MAX - SPEED_MIN);
    s.active = true;
    s.lifeMs = 0;
    s.maxLifeMs = LIFE_BASE_MS + Math.random() * LIFE_VARY_MS;
    s.pos = { x: pos.x, y: pos.y + SPAWN_Y, z: pos.z };
    s.vel = {
      x: Math.cos(azimuth) * Math.cos(elevation) * speed,
      y: Math.sin(elevation) * speed,
      z: Math.sin(azimuth) * Math.cos(elevation) * speed
    };
    Transform2.getMutable(s.entity).position = { ...s.pos };
    claimed++;
  }
}

