      const flutter = Math.sin(s.age * FLUTTER_FREQ * Math.PI * 2 + s.flutterOff) * FLUTTER_AMP;
      s.pos.x += (s.vel.x + flutter) * dt;
      s.pos.y += s.vel.y * dt;
      s.pos.z += (s.vel.z + flutter * 0.55) * dt;
