function initMusicManager() {
  townEntity = engine.addEntity();
  Transform2.create(townEntity, { position: MUSIC_POS });
  AudioSource3.create(townEntity, {
    audioClipUrl: SND_TOWN,
    playing: true,
    loop: true,
    volume: VOL_TOWN
  });
  partyEntity = engine.addEntity();
  Transform2.create(partyEntity, { position: MUSIC_POS });
  AudioSource3.create(partyEntity, {
    audioClipUrl: SND_PARTY,
    playing: false,
    loop: true,
    volume: VOL_PARTY
  });
  console.log("[Music] Manager ready \u2014 Town playing");
  engine.addSystem(() => {
    const pos = Transform2.getOrNull(engine.PlayerEntity)?.position ?? MUSIC_POS;
    Transform2.getMutable(townEntity).position = { x: pos.x, y: pos.y, z: pos.z };
    Transform2.getMutable(partyEntity).position = { x: pos.x, y: pos.y, z: pos.z };
  });
  let lastPhase = "";
  engine.addSystem(() => {
    for (const [, gs] of engine.getEntitiesWith(GameState)) {
      if (gs.phase === lastPhase)
        return;
      const prev = lastPhase;
      lastPhase = gs.phase;
      if (gs.phase === "open" && prev === "playing") {
        stop(townEntity);
        play(partyEntity);
        console.log("[Music] \u2192 Party track");
      } else if (gs.phase === "playing" && prev === "open") {
        stop(partyEntity);
        play(townEntity);
        console.log("[Music] \u2192 Town track");
      }
      return;
    }
  });
}

// src/client/setup.ts
function initClient() {
  console.log("[CLIENT] started");
  initSoundManager();
  initMusicManager();
  initEmoteManager();
  setupUi();
  onEnterSceneObservable.add(() => resetIntro());
  initCleaningSystem();
  initGlassSystem();
  initCollectibleGroup({
    items: discoverBottles(),
    idPrefix: BOTTLE_ID_PREFIX,
    toastKind: "bottles"
  });
  initRubbishSystem();
  initSparkleSystem();
  initStinkSystem();
  initConfettiSystem();
  initEmissionSystem();
  initNarrativeSystem();
}

// src/index.ts
function main() {
  if (isServer()) {
    initServer();
    return;
  }
  initClient();
}

